workspace_files.cache.mjs:
export const STALE_AFTER_MS = 60_000;
export function isStale(entry, now) {
  return now - entry.loadedAt >= STALE_AFTER_MS;
}

workspace_files.session.mjs:
export const IDLE_LIMIT_MS = 60_000;
export function mustSignIn(session, now) {
  return now - session.lastActivityAt >= IDLE_LIMIT_MS;
}

