workspace_files.http.mjs:
export function httpRetry(error, attempt, retryAfterMs = 0) {
  if (attempt >= 4 || !['timeout', 'unavailable'].includes(error)) return null;
  return { delay: Math.max(retryAfterMs, Math.min(1000 * 2 ** attempt, 8000)), scope: 'request' };
}

workspace_files.worker.mjs:
export function workerRetry(error, attempt, paused = false) {
  if (paused || attempt >= 4 || !['timeout', 'unavailable'].includes(error)) return null;
  return { delay: Math.min(1000 * 2 ** attempt, 8000), scope: 'job' };
}

workspace_files.queue.mjs:
export function queueRetry(error, attempt, now = 0) {
  if (attempt >= 4 || !['timeout', 'unavailable'].includes(error)) return null;
  return { scheduledAt: now + Math.min(1000 * 2 ** attempt, 8000), durable: true };
}

