import assert from 'node:assert/strict';
import {httpRetry} from './http.mjs';
import {workerRetry} from './worker.mjs';
import {queueRetry} from './queue.mjs';
for(const error of ['timeout','unavailable','fatal']) for(const attempt of [-1,0,1,3,4,5]) {
 const allowed=attempt<4&&['timeout','unavailable'].includes(error);
 const delay=Math.min(1000*2**attempt,8000);
 for(const retryAfter of [0,2500,10000]) assert.deepEqual(httpRetry(error,attempt,retryAfter),allowed?{delay:Math.max(retryAfter,delay),scope:'request'}:null);
 for(const paused of [false,true]) assert.deepEqual(workerRetry(error,attempt,paused),allowed&&!paused?{delay,scope:'job'}:null);
 for(const now of [0,12345]) assert.deepEqual(queueRetry(error,attempt,now),allowed?{scheduledAt:now+delay,durable:true}:null);
}
assert.deepEqual(httpRetry('timeout',0),{delay:1000,scope:'request'});
assert.deepEqual(workerRetry('timeout',0),{delay:1000,scope:'job'});
assert.deepEqual(queueRetry('timeout',0),{scheduledAt:1000,durable:true});
